@namespace sv_efec28816c9a4ea6a0d0de264532bd4c.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h3 class="product-name">@Product.Name</h3>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" aria-label="@($"Rating: {RatingValue} out of 5")">
            @RatingDisplay
        </div>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int RatingValue => (int)Math.Round(Product.Rating);

    private string RatingDisplay
    {
        get
        {
            var filled = RatingValue;
            var empty = 5 - filled;
            return new string('★', filled) + new string('☆', empty);
        }
    }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }
}

@namespace sv_efec28816c9a4ea6a0d0de264532bd4c.Components.Pages.Catalog

<div class="product-grid">
    @foreach (var product in Products)
    {
        <ProductCard Product="product"
                     OnSelected="OnProductSelected"
                     OnAddToCart="OnAddToCart" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@namespace sv_efec28816c9a4ea6a0d0de264532bd4c.Components.Pages.Catalog

<aside class="catalog-filters">
    <h2>Filters</h2>

    <section class="filter-section">
        <h3>Categories</h3>
        @foreach (var category in Categories)
        {
            <label class="filter-checkbox">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                @category
            </label>
        }
    </section>

    <section class="filter-section">
        <h3>Price Range</h3>
        <label class="filter-label">
            Min Price
            <input type="number" min="0" step="0.01"
                   value="@MinPrice"
                   @onchange="@(e => MinPrice = ParseDecimal(e.Value))" />
        </label>
        <label class="filter-label">
            Max Price
            <input type="number" min="0" step="0.01"
                   value="@MaxPrice"
                   @onchange="@(e => MaxPrice = ParseDecimal(e.Value))" />
        </label>
    </section>

    <section class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@InStockOnly"
                   @onchange="@(e => InStockOnly = (bool)e.Value!)" />
            In Stock Only
        </label>
    </section>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public ProductFilter? CurrentFilter { get; set; }

    [Parameter]
    public EventCallback<ProductFilter> OnFiltersApplied { get; set; }

    [Parameter]
    public EventCallback OnFiltersCleared { get; set; }

    private List<string> SelectedCategories { get; set; } = [];
    private decimal? MinPrice { get; set; }
    private decimal? MaxPrice { get; set; }
    private bool InStockOnly { get; set; }

    protected override void OnParametersSet()
    {
        if (CurrentFilter is not null)
        {
            SelectedCategories = CurrentFilter.Categories?.ToList() ?? [];
            MinPrice = CurrentFilter.MinPrice;
            MaxPrice = CurrentFilter.MaxPrice;
            InStockOnly = CurrentFilter.InStockOnly;
        }
    }

    private bool IsSelected(string category) => SelectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !SelectedCategories.Contains(category))
            SelectedCategories.Add(category);
        else if (!isChecked)
            SelectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: SelectedCategories.Count > 0 ? SelectedCategories.ToList() : null,
            MinPrice: MinPrice,
            MaxPrice: MaxPrice,
            InStockOnly: InStockOnly
        );
        await OnFiltersApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        SelectedCategories = [];
        MinPrice = null;
        MaxPrice = null;
        InStockOnly = false;
        await OnFiltersCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_efec28816c9a4ea6a0d0de264532bd4c.Components.Pages.Catalog

<div class="catalog-toolbar">
    <div class="toolbar-sort">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="toolbar-info">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_efec28816c9a4ea6a0d0de264532bd4c.Components.Pages.Catalog

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product catalog pagination">
        <button class="btn-page"
                disabled="@(CurrentPage <= 1)"
                @onclick="@(() => GoToPage(CurrentPage - 1))">
            Previous
        </button>

        @foreach (var page in GetPageNumbers())
        {
            <button class="btn-page @(page == CurrentPage ? "active" : "")"
                    @onclick="@(() => GoToPage(page))">
                @page
            </button>
        }

        <button class="btn-page"
                disabled="@(CurrentPage >= TotalPages)"
                @onclick="@(() => GoToPage(CurrentPage + 1))">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 7;
        if (TotalPages <= maxVisible)
        {
            return Enumerable.Range(1, TotalPages);
        }

        var start = Math.Max(1, CurrentPage - 3);
        var end = Math.Min(TotalPages, start + maxVisible - 1);
        if (end - start < maxVisible - 1)
        {
            start = Math.Max(1, end - maxVisible + 1);
        }
        return Enumerable.Range(start, end - start + 1);
    }
}

